let text = $input.first().json.choices[0].message.content.trim();
// remove ```json ... ``` fences if the model added them
text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');

const ai = JSON.parse(text);
const candidates = $('Build Prompt').first().json.candidates;

return [{ json: { ai, candidates } }];
